class Solution {
public:
    int countValidWords(string sentence) {
        int n = sentence.size();
        int i = 0;
        int count = 0;
        while (i < n) {
            while (i < n && sentence[i] == ' ') i++;
            if (i >= n) break;
            int start = i;
            while (i < n && sentence[i] != ' ') i++;
            if (isValid(sentence, start, i - 1)) count++;
        }
        return count;
    }

private:
    bool isValid(const string& s, int l, int r) {
        int hyphenCount = 0;
        int punctCount = 0;
        for (int i = l; i <= r; i++) {
            char c = s[i];
            if (c >= '0' && c <= '9') return false;
            if (c == '-') {
                hyphenCount++;
                if (hyphenCount > 1) return false;
                if (i == l || i == r) return false;
                if (!isLower(s[i - 1]) || !isLower(s[i + 1])) return false;
            }
            if (c == '!' || c == '.' || c == ',') {
                punctCount++;
                if (punctCount > 1) return false;
                if (i != r) return false;
            }
        }
        return true;
    }

    bool isLower(char c) {
        return c >= 'a' && c <= 'z';
    }
};
